    headers.append(("Cache-Control", "public"))

    headers.append(("X-XSS-Protection", "0"))
    headers.append(("Strict-Transport-Security", "max-age=0"))

    start_response("200 OK", headers)

    return [ensure_binary(s) for s in response]

